import { createHash } from "node:crypto";
import { interruption } from "./private.mjs";

const digest = (text) => createHash("sha256").update(text).digest("hex");
/** Optional host tool only; no source lookup or prompt injection at registration. */
export function validateApplicationContext(options, reservedNames) {
  if (options === undefined) return;
  const d = options?.descriptor;
  if (
    !options ||
    typeof options.handle !== "function" ||
    d?.type !== "function" ||
    d.name !== "application_context_query" ||
    reservedNames.has(d.name) ||
    d.strict !== true ||
    typeof d.description !== "string" ||
    d.parameters?.type !== "object" ||
    d.parameters.additionalProperties !== false
  )
    throw TypeError("Invalid host application-context tool");
  // Reject values whose wire representation changes at the descriptor boundary.
  const json = JSON.stringify(d);
  if (!json || JSON.stringify(JSON.parse(json)) !== json)
    throw TypeError("Invalid host application-context descriptor");
}
export function createApplicationContextDispatcher(
  options,
  { signal, deadlineAt, observe, save, check },
) {
  validateApplicationContext(options, new Set());
  const calls = [];
  const tools =
    options === undefined
      ? []
      : [JSON.parse(JSON.stringify(options.descriptor))];
  const handler = options?.handle;
  async function call(item, providerResponseId, providerCall) {
    check();
    if (
      !handler ||
      item.name !== tools[0].name ||
      typeof item.call_id !== "string" ||
      !item.call_id ||
      typeof providerResponseId !== "string" ||
      !providerResponseId
    )
      throw Error("Invalid application-context correlation");
    const request = {
      providerResponseId,
      callId: item.call_id,
      functionName: item.name,
      arguments: JSON.parse(item.arguments),
      observations: observe(),
    };
    const row = {
      index: calls.length + 1,
      providerCall,
      request,
      status: "invoked",
      startedAt: new Date().toISOString(),
    };
    calls.push(row);
    await save("application-context-calls.json", calls);
    const remaining = Date.parse(deadlineAt) - Date.now();
    if (remaining <= 0) throw Error("Time limit");
    const timeout = AbortSignal.timeout(remaining),
      callSignal = signal ? AbortSignal.any([timeout, signal]) : timeout;
    let abort;
    const interrupted = new Promise((_, reject) => {
      abort = () =>
        reject(
          Error(signal?.aborted ? interruption(signal).reason : "Time limit"),
        );
      callSignal.addEventListener("abort", abort, { once: true });
      if (callSignal.aborted) abort();
    });
    try {
      check();
      const resultJson = await Promise.race([
        handler(request, callSignal),
        interrupted,
      ]);
      check();
      if (callSignal.aborted)
        throw Error(
          signal?.aborted ? interruption(signal).reason : "Time limit",
        );
      if (typeof resultJson !== "string")
        throw Error("Invalid application-context result");
      row.status = "returned";
      row.resultJson = resultJson;
      row.resultSha256 = digest(resultJson);
      return {
        type: "function_call_output",
        call_id: item.call_id,
        output: resultJson,
      };
    } catch (error) {
      row.status = callSignal.aborted ? "cancelled" : "unresolved";
      // Raw host errors do not become model-visible function results.
      throw error;
    } finally {
      callSignal.removeEventListener("abort", abort);
      row.endedAt = new Date().toISOString();
      await save("application-context-calls.json", calls);
    }
  }
  return { tools, call, calls };
}
